#define BILLION                                 1000000000
static vip_uint64_t get_perf_count()
{
#if defined(__linux__) || defined(__ANDROID__) || defined(__QNX__) || defined(__CYGWIN__)
    struct timespec ts;

    clock_gettime(CLOCK_MONOTONIC, &ts);

    return (vip_uint64_t)((vip_uint64_t)ts.tv_nsec + (vip_uint64_t)ts.tv_sec * BILLION);
#elif defined(_WIN32) || defined(UNDER_CE)
    LARGE_INTEGER ln;

    QueryPerformanceCounter(&ln);

    return (vip_uint64_t)ln.QuadPart;
#endif
}



void dump_pix_coord_info(pix_coord_info_t *coord_info){

    printf("\nFace box number %d\n", coord_info->face_number);
    for(int i = 0; i < coord_info->face_number; i++){
        printf("\nFace %d coord info ", i);
        for(int j = 0; j < API_PER_BOX_ELEMENTS; j++){
            printf("%f, ", coord_info->face_box[i * API_PER_BOX_ELEMENTS + j]);
        }
        printf("\n");
    }
    printf("\n");
}

int get_face_info(pix_image_face_info_t *face_info, const unsigned char *nir_img_ptr, unsigned char *rgb_img_ptr, int is_regest){
    int ret = pix_set_normal_analyze_image(nir_img_ptr, rgb_img_ptr);
    if(SDK_CODE_OK != ret){
        printf("Fail to pix_set_normal_analyze_image with %d\n", ret);
        return ret;
    }
    // ret = pix_fast_fd(nir_img_ptr, &face_info->coord, 1);
    ret = pix_normal_fd(&face_info->coord, &face_info->rgb_coord);
    if(SDK_CODE_OK != ret){
        printf("Fail to pix_normal_fd with %d\n", ret);
        return ret;
    }
    dump_pix_coord_info(&face_info->rgb_coord);

    for(int i = 0; i < face_info->rgb_coord.face_number; i++){

        printf("Get %d face liveness and fr feature\n", i);

        ret = pix_liveness_check(i, &face_info->liveness[i].liveness_score);
        if(SDK_CODE_OK != ret){
            printf("Fail to pix_liveness_check with %d\n", ret);
            return ret;
        }
        if(face_info->liveness[i].liveness_score < pix_get_liveness_threshold()){
            printf("check liveness fail\n");
        }

        ret = pix_get_face_fr_feature(i, &face_info->fr_feature[i], is_regest);
        if(SDK_CODE_OK != ret){
            printf("Fail to pix_get_face_fr_feature with %d\n", ret);
            return ret;
        }
        for(int j = 0; j < API_PER_BOX_ELEMENTS; j++){
            printf("%f, ", face_info->rgb_coord.face_box[i * API_PER_BOX_ELEMENTS + j]);
        }
        printf("\nliveness score: %f \n", face_info->liveness[i].liveness_score);

        printf("pix_get_face_fr_feature end\n");
    }

    return SDK_CODE_OK;

}
