    static float nir_camera_k[6]  = {1605.770388820949, 0.f, 939.920127519846, 0.f, 1606.263924257354, 544.5300005338012};
    pix_set_camera_k(rgb_camera_k, nir_camera_k);
    ret =  pix_init_facekit_model(hard_info, pix_model_ptr, key_bin, key_bin_len);
    if (ret != SDK_CODE_OK)
    {
        printf("pix_init_facekit_model ret: %d\n", ret);
        return -1;
    }

    char *person_1_rgb = NULL;
    char *person_2_rgb = NULL;
    char *person_3_rgb = NULL;
    char *person_1_nir = NULL;
    char *person_2_nir = NULL;
    char *person_3_nir = NULL;
    person_1_rgb = argv[1];
    person_2_rgb = argv[3];
    person_3_rgb = argv[5];
    person_1_nir = argv[2];
    person_2_nir = argv[4];
    person_3_nir = argv[6];
    printf("person_1_rgb: %s person_1_nir: %s\n", person_1_rgb, person_1_nir);
    printf("person_2_rgb: %s person_2_nir: %s\n", person_2_rgb, person_2_nir);
    printf("person_3_rgb: %s person_3_nir: %s\n", person_3_rgb, person_3_nir);
    unsigned char *person_1_ptr_rgb = NULL;
    unsigned char *person_2_ptr_rgb = NULL;
    unsigned char *person_3_ptr_rgb = NULL;
    unsigned char *person_1_ptr_nir = NULL;
    unsigned char *person_2_ptr_nir = NULL;
    unsigned char *person_3_ptr_nir = NULL;
    person_1_ptr_rgb = (unsigned char *)malloc(sizeof(unsigned char) * ALLWINNER_PIC_HEIGHT * ALLWINNER_PIC_WEIGHT * 3 / 2);
    person_2_ptr_rgb = (unsigned char *)malloc(sizeof(unsigned char) * ALLWINNER_PIC_HEIGHT * ALLWINNER_PIC_WEIGHT * 3 / 2);
    person_3_ptr_rgb = (unsigned char *)malloc(sizeof(unsigned char) * ALLWINNER_PIC_HEIGHT * ALLWINNER_PIC_WEIGHT * 3 / 2);
    person_1_ptr_nir = (unsigned char *)malloc(sizeof(unsigned char) * ALLWINNER_PIC_HEIGHT * ALLWINNER_PIC_WEIGHT * 3 / 2);
    person_2_ptr_nir = (unsigned char *)malloc(sizeof(unsigned char) * ALLWINNER_PIC_HEIGHT * ALLWINNER_PIC_WEIGHT * 3 / 2);
    person_3_ptr_nir = (unsigned char *)malloc(sizeof(unsigned char) * ALLWINNER_PIC_HEIGHT * ALLWINNER_PIC_WEIGHT * 3 / 2);

    load_file(person_1_rgb, person_1_ptr_rgb);
    load_file(person_2_rgb, person_2_ptr_rgb);
    load_file(person_3_rgb, person_3_ptr_rgb);
    load_file(person_1_nir, person_1_ptr_nir);
    load_file(person_2_nir, person_2_ptr_nir);
    load_file(person_3_nir, person_3_ptr_nir);

    pix_image_face_info_t *person1_face_info, *person2_face_info, *person3_face_info;
    person1_face_info = (pix_image_face_info_t *) malloc(sizeof(pix_image_face_info_t));
    person2_face_info = (pix_image_face_info_t *) malloc(sizeof(pix_image_face_info_t));
    person3_face_info = (pix_image_face_info_t *) malloc(sizeof(pix_image_face_info_t));


    unsigned long long sigStart, sigEnd;
    float msVal, usVal;
    sigStart = get_perf_count();
    ret = get_face_info(person1_face_info, person_1_ptr_nir, person_1_ptr_rgb, 0);
    if (ret != SDK_CODE_OK){
        printf("Fail to get person1 face info\n");
        goto end;
    }
    sigEnd = get_perf_count();
    msVal = (float)(sigEnd - sigStart)/1000000;
    usVal = (float)(sigEnd - sigStart)/1000;
//    printf("Run the time: %.2fms or %.2fus\n", msVal, usVal);


    ret = get_face_info(person2_face_info, person_2_ptr_nir, person_2_ptr_rgb, 1);
